"""Validates and formats empirical receipts files generated by Sarathi workers."""

from __future__ import annotations

import os
import pathlib
import re
from typing import Any


def verify_receipts(receipt_path: str) -> dict[str, Any]:
  """Parses and validates an empirical receipts file.

  A valid receipts file must adhere to the contract:
  1. File exists and is non-empty.
  2. Contains a ```bash code fence with the executed test command.
  3. Contains an `Output:` section followed by verbatim test output.
  4. Indicates a successful exit code (exit code 0).

  Args:
    receipt_path: Path to the receipts file to inspect.

  Returns:
    Dict containing validation status, parsed command, exit code, and any errors.
  """
  resolved_path = str(pathlib.Path(receipt_path).resolve())
  errors: list[str] = []

  if not os.path.exists(resolved_path):
    return {
        "valid": False,
        "receipt_path": resolved_path,
        "passed": False,
        "errors": [f"Receipts file does not exist: {resolved_path}"],
    }

  if os.path.getsize(resolved_path) == 0:
    return {
        "valid": False,
        "receipt_path": resolved_path,
        "passed": False,
        "errors": [f"Receipts file is empty: {resolved_path}"],
    }

  try:
    with open(resolved_path, "r", encoding="utf-8", errors="replace") as f:
      content = f.read()
  except Exception as e:
    return {
        "valid": False,
        "receipt_path": resolved_path,
        "passed": False,
        "errors": [f"Failed to read receipts file: {str(e)}"],
    }

  # Parse command from ```bash ... ```
  cmd_match = re.search(r"```(?:bash|sh)\s*\n(.*?)\n```", content, re.DOTALL)
  command = cmd_match.group(1).strip() if cmd_match else ""
  if not command:
    errors.append("Missing or malformed test command in ```bash code fence.")

  # Parse exit code (e.g. `Exit code: 0` or `exit code 0`)
  exit_code: int | None = None
  exit_match = re.search(r"(?:Exit code|exit code|exited with code)[\s:=]+(\d+)", content)
  if exit_match:
    exit_code = int(exit_match.group(1))
  elif "PASSED" in content or "ok" in content.lower() or "100%" in content:
    # If no explicit exit code line, check for clean passing keywords
    exit_code = 0
  else:
    errors.append("No exit code found in receipts file.")

  # Extract output snippet
  output_snippet = ""
  output_match = re.search(r"Output:\s*\n```(?:text)?\s*\n(.*?)\n```", content, re.DOTALL)
  if output_match:
    output_snippet = output_match.group(1).strip()[:500]
  else:
    # Fallback to reading first 500 chars after command
    output_snippet = content[len(command) + 50 : len(command) + 550].strip()

  is_passed = (exit_code == 0) and len(errors) == 0

  return {
      "valid": len(errors) == 0,
      "receipt_path": resolved_path,
      "command": command,
      "exit_code": exit_code if exit_code is not None else -1,
      "passed": is_passed,
      "output_snippet": output_snippet,
      "errors": errors,
  }


def create_receipt_file(
    receipt_path: str,
    command: str,
    exit_code: int,
    output: str,
) -> str:
  """Helper to write a properly formatted receipts file.

  Args:
    receipt_path: Target file path.
    command: The terminal command executed.
    exit_code: Process return code.
    output: Full terminal output.

  Returns:
    The resolved absolute path of the created receipts file.
  """
  resolved = str(pathlib.Path(receipt_path).resolve())
  os.makedirs(os.path.dirname(resolved), exist_ok=True)

  formatted = f"""# Verification Receipt

```bash
{command}
```

Exit code: {exit_code}

Output:
```text
{output.strip()}
```
"""
  with open(resolved, "w", encoding="utf-8") as f:
    f.write(formatted)

  return resolved
